// This file was generated by Prisma and assumes you have installed the following:
// npm install --save-dev prisma dotenv
import dotenv from 'dotenv';
import { defineConfig } from 'prisma/config';

// Next.js 约定优先加载 .env.local，其次 .env；Prisma CLI 不经过 Next 的加载器，
// 这里保持同一优先级，避免「应用能读到、prisma db push 读不到」的割裂
dotenv.config({ path: '.env.local' });
dotenv.config({ path: '.env' });

const baseConfig = {
  schema: 'prisma/schema.prisma',
  migrations: {
    path: 'prisma/migrations',
  },
};

// 需要真实数据库连接的命令：缺配置时立刻给出明确报错，
// 而不是让 generate 的占位串在连接阶段报出难懂的 P1001
const CONNECTION_COMMANDS = new Set(['db', 'migrate', 'studio']);
if (!process.env.DATABASE_URL && CONNECTION_COMMANDS.has(process.argv[2] ?? '')) {
  throw new Error(
    'DATABASE_URL 未配置：请在 .env.local 或环境中设置 PostgreSQL 连接串后再运行该命令'
  );
}

export default defineConfig({
  ...baseConfig,
  engine: 'classic' as const,
  // prisma generate 等离线命令不会真正连接数据库；
  // 缺少连接串时用占位值满足必填类型，连接类命令已在上方被明确拦截
  datasource: {
    url:
      process.env.DATABASE_URL || 'postgresql://placeholder:placeholder@localhost:5432/placeholder',
  },
});
